#include <bits/stdc++.h>
using namespace std;

typedef pair<long long, int> Entry;  // (score, column)
const long long NEG = -(1LL << 62);

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<long long> a((size_t)n * m);
    for (auto &x : a) cin >> x;
    // the two best scores of earlier rows, kept in different columns
    array<Entry, 2> best = {Entry{NEG, -1}, Entry{NEG, -2}};
    long long answer = NEG;
    for (int i = 0; i < n; i++) {
        // query the whole row first so no pair shares a row
        for (int j = 0; j < m; j++) {
            long long other = NEG;
            for (auto &[score, col] : best)
                if (col != j) other = max(other, score);
            answer = max(answer, a[(size_t)i * m + j] + other);
        }
        for (int j = 0; j < m; j++) {
            long long v = a[(size_t)i * m + j];
            vector<Entry> cand;
            bool merged = false;
            for (auto &[score, col] : best) {
                if (col == j) cand.push_back({max(score, v), col}), merged = true;
                else cand.push_back({score, col});
            }
            if (!merged) cand.push_back({v, j});
            sort(cand.rbegin(), cand.rend());
            best = {cand[0], cand[1]};
        }
    }
    cout << answer << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (buf[pos] <= ' ') pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    static final long NEG = -(1L << 62);

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt(), m = nextInt();
        long[] a = new long[n * m];
        for (int i = 0; i < n * m; i++) a[i] = nextLong();
        // the two best scores of earlier rows, kept in different columns (score desc, then column desc)
        long[] score = {NEG, NEG};
        int[] col = {-1, -2};
        long answer = NEG;
        long[] cs = new long[3];
        int[] cc = new int[3];
        for (int i = 0; i < n; i++) {
            // query the whole row first so no pair shares a row
            for (int j = 0; j < m; j++) {
                long other = NEG;
                for (int t = 0; t < 2; t++) if (col[t] != j) other = Math.max(other, score[t]);
                answer = Math.max(answer, a[i * m + j] + other);
            }
            for (int j = 0; j < m; j++) {
                long v = a[i * m + j];
                int size = 0;
                boolean merged = false;
                for (int t = 0; t < 2; t++) {
                    cs[size] = col[t] == j ? Math.max(score[t], v) : score[t];
                    merged |= col[t] == j;
                    cc[size++] = col[t];
                }
                if (!merged) {
                    cs[size] = v;
                    cc[size++] = j;
                }
                // keep the top two by (score, column)
                for (int t = 0; t < 2; t++)
                    for (int u = t + 1; u < size; u++)
                        if (cs[u] > cs[t] || (cs[u] == cs[t] && cc[u] > cc[t])) {
                            long ts = cs[t];
                            cs[t] = cs[u];
                            cs[u] = ts;
                            int tc = cc[t];
                            cc[t] = cc[u];
                            cc[u] = tc;
                        }
                score[0] = cs[0];
                col[0] = cc[0];
                score[1] = cs[1];
                col[1] = cc[1];
            }
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Split(bufio.ScanWords)
	next := func() int {
		sc.Scan()
		v, _ := strconv.Atoi(sc.Text())
		return v
	}
	n, m := next(), next()
	a := make([]int, n*m)
	for i := range a {
		a[i] = next()
	}
	const NEG = -(1 << 62)
	type entry struct{ score, col int }
	// the two best scores of earlier rows, kept in different columns
	best := []entry{{NEG, -1}, {NEG, -2}}
	answer := NEG
	cand := make([]entry, 0, 3)
	for i := 0; i < n; i++ {
		// query the whole row first so no pair shares a row
		for j := 0; j < m; j++ {
			other := NEG
			for _, e := range best {
				if e.col != j {
					other = max(other, e.score)
				}
			}
			answer = max(answer, a[i*m+j]+other)
		}
		for j := 0; j < m; j++ {
			v := a[i*m+j]
			cand = cand[:0]
			merged := false
			for _, e := range best {
				if e.col == j {
					e.score = max(e.score, v)
					merged = true
				}
				cand = append(cand, e)
			}
			if !merged {
				cand = append(cand, entry{v, j})
			}
			// keep the top two by (score, column)
			sort.Slice(cand, func(p, q int) bool {
				if cand[p].score != cand[q].score {
					return cand[p].score > cand[q].score
				}
				return cand[p].col > cand[q].col
			})
			best[0], best[1] = cand[0], cand[1]
		}
	}
	fmt.Println(answer)
}
